function avatarPickerHtml(selectedIdx){
  const items = AVATAR_LIBRARY.map((src,i)=>`
    <button type="button" class="avatar-pick-item ${selectedIdx===i?'selected':''}" data-pick-idx="${i}">
      <img src="${src}" alt="">
    </button>`).join('');
  return `<div class="field-label">Pilih Avatar</div>
    <div class="avatar-picker-grid">
      <button type="button" class="avatar-pick-item none-item ${selectedIdx===-1?'selected':''}" data-pick-idx="-1">Pakai Ilustrasi</button>
      ${items}
    </div>`;
}
function bindAvatarPicker(getSet){
  document.querySelectorAll('[data-pick-idx]').forEach(btn=>{
    btn.onclick = ()=>{
      getSet(parseInt(btn.dataset.pickIdx,10));
      document.querySelectorAll('[data-pick-idx]').forEach(b=>b.classList.toggle('selected', b.dataset.pickIdx===btn.dataset.pickIdx));
    };
  });
}
function findLibraryIdx(s){
  if(!s) return -1;
  return typeof s.avatarLib === 'number' ? s.avatarLib : -1;
}

function openAddStudent(){
  let gender = 'L';
  let avIdx = -1;
  openModal('Tambah Siswa', `
    <div class="field-label">Nama Lengkap</div>
    <input class="text-input" id="sName" placeholder="Contoh: Zaid Abdullah" />
    ${genderSegHtml(gender)}
    ${avatarPickerHtml(avIdx)}
  `, `<button class="save-btn" id="sSaveBtn">Simpan Siswa</button>`);
  bindGenderSeg((v)=>{ gender = v; });
  bindAvatarPicker((v)=>{ avIdx = v; });
  document.getElementById('sSaveBtn').onclick = ()=>{
    const name = document.getElementById('sName').value.trim();
    if(!name) return;
    const student = {id:uid(), name, avatarIdx: state.students.length, gender, points:0};
    if(avIdx>=0) student.avatarLib = avIdx;
    state.students.push(student);
    saveAndRender();
    closeModal();
  };
}

function openEditStudent(id){
  const s = state.students.find(x=>x.id===id);
  if(!s) return;
  let gender = s.gender==='P' ? 'P' : 'L';
  let avIdx = findLibraryIdx(s);
  openModal('Edit Siswa', `
    <div class="field-label">Nama Lengkap</div>
    <input class="text-input" id="sName" value="${s.name.replace(/"/g,'&quot;')}" />
    ${genderSegHtml(gender)}
    ${avatarPickerHtml(avIdx)}
  `, `<button class="save-btn" id="sSaveBtn">Simpan Perubahan</button>`);
  bindGenderSeg((v)=>{ gender = v; });
  bindAvatarPicker((v)=>{ avIdx = v; });
  document.getElementById('sSaveBtn').onclick = ()=>{
    const name = document.getElementById('sName').value.trim();
    if(!name) return;
    s.name = name;
    s.gender = gender;
    delete s.photo;
    if(avIdx>=0){ s.avatarLib = avIdx; delete s.avatarKey; }
    else{ delete s.avatarLib; delete s.avatarKey; }
    saveAndRender();
    closeModal();
  };
}

function deleteStudent(id){
  const s = state.students.find(x=>x.id===id);
  if(!s) return;
  if(!confirm(`Hapus ${s.name} dari kelas?`)) return;
  state.students = state.students.filter(x=>x.id!==id);
  saveAndRender();
}

function openStudentDetail(id){
  const s = state.students.find(x=>x.id===id);
  if(!s) return;
  const st = avatarStyle(s.avatarIdx ?? 0);
  const logs = state.logs.filter(l=>l.studentId===id).slice(0,20);
  const logRows = logs.map(l=>{
    const a = ACTIONS[l.type] || {icon:'⭐', label:'Poin'};
    return `<div class="form-row">
      <div class="av-sm" style="background:var(--sage-soft);color:var(--header)">${a.icon}</div>
      <div class="fname">${a.label}${l.note?' · '+l.note:''}<div class="mini-note">${l.date}</div></div>
      <div style="font-weight:800;color:${l.delta>=0?'var(--gold-deep)':'var(--danger)'};font-size:13px;">${l.delta>=0?'+':''}${l.delta}</div>
    </div>`;
  }).join('') || '<div class="empty-note">Belum ada riwayat.</div>';

  openModal(s.name, `
    <div style="text-align:center;margin-bottom:14px;">
      <div class="avatar-ring" style="background:${st.bg};margin:0 auto 8px;width:70px;height:70px;">${avatarOf(s)}</div>
      <div class="pt-pill" style="font-size:14px;padding:5px 14px;">⭐ ${s.points} Poin</div>
    </div>
    <div class="field-label">Riwayat Aktivitas</div>
    ${logRows}
  `, `
    <div class="qty-ctrl" style="justify-content:center;gap:14px;">
      <button class="qty-btn" id="detMinus" style="width:36px;height:36px;font-size:16px;">−5</button>
      <span style="font-weight:800;font-size:12px;color:var(--ink-soft);">Poin Cepat</span>
      <button class="qty-btn" id="detPlus" style="width:36px;height:36px;font-size:16px;">+5</button>
    </div>
  `);
  document.getElementById('detPlus').onclick = ()=>{
    const {touched,totalPositive} = applyDeltas([{studentId:id, delta:5}], 'Tambahan cepat', 'poin');
    closeModal();
    showCelebration(totalPositive, `${s.name.split(' ')[0]} mendapat tambahan poin!`, touched);
  };
  document.getElementById('detMinus').onclick = ()=>{
    applyDeltas([{studentId:id, delta:-5}], 'Pengurangan cepat', 'poin');
    closeModal();
    showToast(`${s.name.split(' ')[0]} -5 poin`);
  };
}

/* ---------------- ACTION MODALS ---------------- */
function studentRowsTemplate(renderRight){
  return (state.students||[]).map((s,i)=>{
    const st = avatarStyle(s.avatarIdx ?? i);
    return `<div class="form-row" data-row-id="${s.id}">
      <div class="av-sm" style="background:${st.bg}">${avatarOf(s)}</div>
      <div class="fname">${s.name.split(' ')[0]}</div>
      ${renderRight(s)}
    </div>`;
  }).join('');
}

function openActionModal(key){
  if(key==='absensi') return openAbsensiModal();
  if(key==='nilai') return openNilaiModal();
  if(key==='ujian') return openUjianModal();
  if(key==='piket') return openPiketModal();
  if(key==='quran') return openQuranModal();
  if(key==='poin') return openPoinModal();
}

/* --- ABSENSI --- */
function openAbsensiModal(){
  const statuses = {};
  (state.students||[]).forEach(s=> statuses[s.id]='Hadir');
  const STATUS_PTS = {Hadir:5, Sakit:0, Izin:0, Alpa:-2};
  const opts = ['Hadir','Sakit','Izin','Alpa'];

  function rowsHtml(){
    return studentRowsTemplate((s)=>`
      <div class="seg" data-seg-for="${s.id}">
        ${opts.map(o=>`<button data-seg-btn="${s.id}" data-val="${o}" class="${statuses[s.id]===o?'on':''}">${o}</button>`).join('')}
      </div>`);
  }
  openModal('Absensi Hari Ini', `<div id="absRows">${rowsHtml()}</div>`, `<button class="save-btn" id="absSave">Simpan Absensi</button>`);

  function bindSegs(){
    document.querySelectorAll('[data-seg-btn]').forEach(btn=>{
      btn.onclick = ()=>{
        const id = btn.dataset.segBtn;
        statuses[id] = btn.dataset.val;
        document.querySelectorAll(`[data-seg-btn="${id}"]`).forEach(b=>b.classList.toggle('on', b.dataset.val===statuses[id]));
      };
    });
  }
  bindSegs();

  document.getElementById('absSave').onclick = ()=>{
    const deltas = Object.entries(statuses).map(([studentId,st])=>({studentId, delta:STATUS_PTS[st]}));
    const hadirCount = Object.values(statuses).filter(v=>v==='Hadir').length;
    const {touched,totalPositive} = applyDeltas(deltas, 'Absensi', 'absensi');
    closeModal();
    showCelebration(totalPositive, `Absensi tersimpan! ${hadirCount} siswa hadir hari ini.`, touched);
  };
}

/* --- NILAI HARIAN --- */
function openNilaiModal(){
  const scores = {};
  function rowsHtml(){
    return studentRowsTemplate((s)=>`
      <input type="number" min="0" max="100" class="num-input" placeholder="—" data-score-for="${s.id}" />`);
  }
  openModal('Nilai Harian', `
    <div class="field-label">Mata Pelajaran</div>
    <input class="text-input" id="nSubject" placeholder="Contoh: Bahasa Arab" />
    <div class="field-label">Nilai per Siswa (0–100, kosongkan jika belum dinilai)</div>
    <div id="nRows">${rowsHtml()}</div>
  `, `<button class="save-btn" id="nSave">Simpan Nilai</button>`);

  document.getElementById('nSave').onclick = ()=>{
    const subject = document.getElementById('nSubject').value.trim() || 'Nilai Harian';
    const deltas = [];
    document.querySelectorAll('[data-score-for]').forEach(inp=>{
      const v = inp.value.trim();
      if(v==='') return;
      const score = clamp(parseInt(v,10)||0,0,100);
      deltas.push({studentId:inp.dataset.scoreFor, delta:Math.round(score/10)});
    });
    if(deltas.length===0){ closeModal(); return; }
    const {touched,totalPositive} = applyDeltas(deltas, subject, 'nilai');
    closeModal();
    showCelebration(totalPositive, `Nilai "${subject}" tersimpan untuk ${deltas.length} siswa.`, touched);
  };
}

/* --- UJIAN --- */
function openUjianModal(){
  function rowsHtml(){
    return studentRowsTemplate((s)=>`
      <input type="number" min="0" max="100" class="num-input" placeholder="—" data-score-for="${s.id}" />`);
  }
  openModal('Ujian', `
    <div class="field-label">Nama Ujian</div>
    <input class="text-input" id="uName" placeholder="Contoh: Ujian Tengah Semester" />
    <div class="field-label">Nilai per Siswa (0–100, kosongkan jika belum ujian)</div>
    <div id="uRows">${rowsHtml()}</div>
  `, `<button class="save-btn" id="uSave">Simpan Ujian</button>`);

  document.getElementById('uSave').onclick = ()=>{
    const examName = document.getElementById('uName').value.trim() || 'Ujian';
    const deltas = [];
    document.querySelectorAll('[data-score-for]').forEach(inp=>{
      const v = inp.value.trim();
      if(v==='') return;
      const score = clamp(parseInt(v,10)||0,0,100);
      deltas.push({studentId:inp.dataset.scoreFor, delta:Math.round(score/5)});
    });
    if(deltas.length===0){ closeModal(); return; }
    const {touched,totalPositive} = applyDeltas(deltas, examName, 'ujian');
    closeModal();
    showCelebration(totalPositive, `Hasil "${examName}" tersimpan untuk ${deltas.length} siswa.`, touched);
  };
}

/* --- PIKET --- */
function openPiketModal(){
  let selectedDay = dayName()==='Minggu' ? 'Senin' : dayName();
  if(!DAYS.includes(selectedDay)) selectedDay = 'Senin';
  const doneToday = new Set();

  function assignedIds(){ return state.piket[selectedDay] || []; }

  function bodyHtml(){
    const dayTabs = DAYS.map(d=>`<button class="day-tab ${d===selectedDay?'active':''}" data-day="${d}">${d}</button>`).join('');
    const assigned = assignedIds();
    const rows = (state.students||[]).map((s,i)=>{
      const st = avatarStyle(s.avatarIdx ?? i);
      const isAssigned = assigned.includes(s.id);
      return `<div class="form-row">
        <div class="av-sm" style="background:${st.bg}">${avatarOf(s)}</div>
        <div class="fname">${s.name.split(' ')[0]}</div>
        <button class="chk-box ${isAssigned?'on':''}" data-assign-toggle="${s.id}">${isAssigned?'✓':''}</button>
      </div>`;
    }).join('');
    return `
      <div class="day-tabs">${dayTabs}</div>
      <div class="field-label">Petugas Piket Hari ${selectedDay}</div>
      <div id="piketRows">${rows}</div>
      <div class="mini-note" style="margin-top:8px;">Centang siswa yang bertugas piket pada hari ini. Simpan jadwal untuk minggu depan, atau tandai selesai jika piket hari ini sudah dikerjakan.</div>
    `;
  }

  function footHtml(){
    return `
      <div style="display:flex;gap:8px;">
        <button class="save-btn" style="flex:1;background:var(--sage-soft);color:var(--header);" id="piketSaveSchedule">Simpan Jadwal</button>
        ${selectedDay===dayName() ? `<button class="save-btn" style="flex:1;" id="piketMarkDone">Tandai Selesai +5</button>` : ''}
      </div>`;
  }

  function draw(){
    openModal('Jadwal Piket', bodyHtml(), footHtml());
    document.querySelectorAll('[data-day]').forEach(btn=>{
      btn.onclick = ()=>{ selectedDay = btn.dataset.day; draw(); };
    });
    document.querySelectorAll('[data-assign-toggle]').forEach(btn=>{
      btn.onclick = ()=>{
        const id = btn.dataset.assignToggle;
        const arr = state.piket[selectedDay] || [];
        state.piket[selectedDay] = arr.includes(id) ? arr.filter(x=>x!==id) : [...arr, id];
        draw();
      };
    });
    const saveBtn = document.getElementById('piketSaveSchedule');
    if(saveBtn) saveBtn.onclick = ()=>{ saveAndRender(); closeModal(); showToast('Jadwal piket disimpan'); };
    const doneBtn = document.getElementById('piketMarkDone');
    if(doneBtn) doneBtn.onclick = ()=>{
      const ids = assignedIds();
      if(ids.length===0){ showToast('Belum ada siswa yang bertugas hari ini'); return; }
      const deltas = ids.map(id=>({studentId:id, delta:5}));
      const {touched,totalPositive} = applyDeltas(deltas, 'Piket selesai', 'piket');
      closeModal();
      showCelebration(totalPositive, `Piket hari ${selectedDay} selesai dikerjakan!`, touched);
    };
  }
  draw();
}

/* --- DARUS & MUROJAAH --- */
function openQuranModal(){
  let mode = 'darus'; // darus | murojaah
  const notes = {};
  const checked = {};

  function bodyHtml(){
    const rows = (state.students||[]).map((s,i)=>{
      const st = avatarStyle(s.avatarIdx ?? i);
      return `<div class="form-row">
        <div class="av-sm" style="background:${st.bg}">${avatarOf(s)}</div>
        <div class="fname" style="min-width:64px;">${s.name.split(' ')[0]}</div>
        <input class="text-input" style="margin:0;flex:1;padding:7px 10px;font-size:12px;" placeholder="Surat / Ayat" data-qnote="${s.id}" value="${notes[s.id]||''}" />
        <button class="chk-box ${checked[s.id]?'on':''}" data-qchk="${s.id}">${checked[s.id]?'✓':''}</button>
      </div>`;
    }).join('');
    return `
      <div class="tab-toggle">
        <button class="${mode==='darus'?'active':''}" data-qmode="darus">📖 Darus Qur'an</button>
        <button class="${mode==='murojaah'?'active':''}" data-qmode="murojaah">🔁 Murojaah</button>
      </div>
      <div class="field-label">Centang siswa yang setor hari ini (+3 poin)</div>
      <div id="qRows">${rows}</div>
    `;
  }

  function draw(){
    openModal("Darus & Murojaah", bodyHtml(), `<button class="save-btn" id="qSave">Simpan ${mode==='darus'?'Darus':'Murojaah'}</button>`);
    document.querySelectorAll('[data-qmode]').forEach(btn=>{
      btn.onclick = ()=>{ mode = btn.dataset.qmode; draw(); };
    });
    document.querySelectorAll('[data-qnote]').forEach(inp=>{
      inp.oninput = ()=>{ notes[inp.dataset.qnote] = inp.value; };
    });
    document.querySelectorAll('[data-qchk]').forEach(btn=>{
      btn.onclick = ()=>{
        const id = btn.dataset.qchk;
        checked[id] = !checked[id];
        draw();
      };
    });
    document.getElementById('qSave').onclick = ()=>{
      const deltas = Object.keys(checked).filter(id=>checked[id]).map(id=>({studentId:id, delta:3}));
      if(deltas.length===0){ closeModal(); return; }
      const noteSample = mode==='darus' ? 'Setoran bacaan' : 'Murojaah hafalan';
      const {touched,totalPositive} = applyDeltas(deltas, noteSample, mode);
      closeModal();
      showCelebration(totalPositive, `${mode==='darus'?'Darus':'Murojaah'} tersimpan untuk ${deltas.length} siswa.`, touched);
    };
  }
  draw();
}

/* --- POIN MANUAL --- */
function openPoinModal(){
  const qty = {};
  (state.students||[]).forEach(s=> qty[s.id]=0);

  function rowsHtml(){
    return studentRowsTemplate((s)=>`
      <div class="qty-ctrl">
        <button class="qty-btn" data-qminus="${s.id}">−</button>
        <span class="qty-val" data-qval="${s.id}">${qty[s.id]}</span>
        <button class="qty-btn" data-qplus="${s.id}">+</button>
      </div>`);
  }
  openModal('Poin Manual', `
    <div class="field-label">Alasan</div>
    <input class="text-input" id="pReason" placeholder="Contoh: Berani tampil di depan kelas" />
    <div class="field-label">Atur Poin per Siswa</div>
    <div id="pRows">${rowsHtml()}</div>
  `, `<button class="save-btn" id="pSave">Simpan Poin</button>`);

  function bind(){
    document.querySelectorAll('[data-qplus]').forEach(btn=>{
      btn.onclick = ()=>{ const id=btn.dataset.qplus; qty[id]++; document.querySelector(`[data-qval="${id}"]`).textContent=qty[id]; };
    });
    document.querySelectorAll('[data-qminus]').forEach(btn=>{
      btn.onclick = ()=>{ const id=btn.dataset.qminus; qty[id]--; document.querySelector(`[data-qval="${id}"]`).textContent=qty[id]; };
    });
  }
  bind();

  document.getElementById('pSave').onclick = ()=>{
    const reason = document.getElementById('pReason').value.trim() || 'Poin tambahan';
    const deltas = Object.entries(qty).filter(([,v])=>v!==0).map(([studentId,delta])=>({studentId, delta}));
    if(deltas.length===0){ closeModal(); return; }
    const {touched,totalPositive} = applyDeltas(deltas, reason, 'poin');
    closeModal();
    showCelebration(totalPositive, `${reason} — poin diberikan ke ${deltas.length} siswa.`, touched);
  };
}

/* ---------------- NAV BINDINGS ---------------- */
document.querySelectorAll('.nav-btn').forEach(btn=>{
  btn.addEventListener('click', ()=>{ activeTab = btn.dataset.tab; render(); });
});
document.getElementById('gearBtn').addEventListener('click', ()=>{ activeTab='profil'; render(); });

initApp();
